import{_ as s,o as t,c as i,a3 as o}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Model Context Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"en/customization/mcp.md","filePath":"en/customization/mcp.md"}'),a={name:"en/customization/mcp.md"};function n(l,e,r,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/customization/mcp.md for this page in Markdown format</div><h1 id="model-context-protocol" tabindex="-1">Model Context Protocol <a class="header-anchor" href="#model-context-protocol" aria-label="Permalink to &quot;Model Context Protocol&quot;">​</a></h1><p><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol (MCP)</a> is an open protocol that lets models safely call tools exposed by external processes or services — for example, reading GitHub issues, querying databases, or operating the local file system. Kimi Code CLI acts as an MCP client to connect these external tools and exposes them to the Agent alongside built-in tools (<code>Read</code>, <code>Bash</code>, <code>Grep</code>, etc.) with no behavioral difference.</p><h2 id="connection-methods" tabindex="-1">Connection Methods <a class="header-anchor" href="#connection-methods" aria-label="Permalink to &quot;Connection Methods&quot;">​</a></h2><p>Kimi Code CLI supports three MCP server connection methods:</p><ul><li><strong>stdio</strong>: The CLI starts the local MCP server as a child process and communicates via standard input/output. Suitable for local command-line tools.</li><li><strong>HTTP</strong>: The CLI connects to an already-running HTTP endpoint. Suitable for remote services or processes that need to run persistently.</li><li><strong>SSE</strong>: The CLI connects to a legacy HTTP+SSE endpoint (Server-Sent Events, a streaming HTTP mechanism). Prefer HTTP for new MCP servers, but use <code>transport: &quot;sse&quot;</code> when a service still exposes only the older SSE transport.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>MCP server configuration is written in <code>mcp.json</code>, at two levels:</p><ul><li><strong>User level</strong>: <code>~/.kimi-code/mcp.json</code> (or <code>$KIMI_CODE_HOME/mcp.json</code>), shared across projects</li><li><strong>Project level</strong>: <code>.kimi-code/mcp.json</code> in the working directory, effective only for the current repository</li></ul><p>Entries with the same name: the project-level entry takes precedence and overrides the user-level entry.</p><p>Run <code>/mcp-config</code> in the TUI to interactively add, edit, or delete servers without manually editing the JSON file. Run <code>/mcp</code> to view the connection status of all current servers.</p><p>Structure of <code>mcp.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tmp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;linear&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.linear.app/mcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;legacy-events&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;transport&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sse&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.example.com/sse&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Entries with a <code>command</code> field are stdio servers; entries with a <code>url</code> field and no <code>transport</code> are HTTP servers. For legacy SSE servers, set <code>transport</code> to <code>&quot;sse&quot;</code> explicitly.</p><p>Optional fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Applies to</th><th>Description</th></tr></thead><tbody><tr><td><code>env</code></td><td><code>Record&lt;string, string&gt;</code></td><td>stdio</td><td>Environment variables injected into the child process</td></tr><tr><td><code>cwd</code></td><td><code>string</code></td><td>stdio</td><td>Working directory for the child process</td></tr><tr><td><code>headers</code></td><td><code>Record&lt;string, string&gt;</code></td><td>HTTP, SSE</td><td>Static request headers appended to every request</td></tr><tr><td><code>bearerTokenEnvVar</code></td><td><code>string</code></td><td>HTTP, SSE</td><td>Name of an environment variable that contains a bearer token</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td>All</td><td>Set to <code>false</code> to disable this server</td></tr><tr><td><code>startupTimeoutMs</code></td><td><code>number</code></td><td>All</td><td>Connection timeout from <code>1</code> to <code>2147483647</code> milliseconds; default <code>30000</code></td></tr><tr><td><code>toolTimeoutMs</code></td><td><code>number</code></td><td>All</td><td>Timeout from <code>1</code> to <code>2147483647</code> milliseconds for a single tool call</td></tr><tr><td><code>enabledTools</code></td><td><code>string[]</code></td><td>All</td><td>Tool allowlist</td></tr><tr><td><code>disabledTools</code></td><td><code>string[]</code></td><td>All</td><td>Tool blocklist</td></tr></tbody></table><p>You do not have to set the connection timeout or the single tool-call timeout per server: <code>[mcp] startup_timeout_ms</code> / <code>[mcp] tool_timeout_ms</code> in <code>config.toml</code> or the <code>KIMI_MCP_STARTUP_TIMEOUT_MS</code> / <code>KIMI_MCP_TOOL_TIMEOUT_MS</code> environment variables change the global defaults. Precedence is: per-server field &gt; environment variable &gt; <code>config.toml</code> &gt; built-in default. See <a href="./../configuration/config-files.html#mcp">Configuration files</a>.</p><p>HTTP and SSE servers support providing static credentials via <code>headers</code> or <code>bearerTokenEnvVar</code>. When OAuth is needed, run <code>/mcp-config login &lt;server-name&gt;</code> to complete browser-based authorization.</p><p>Plugins can also declare MCP servers in their manifest. Servers declared by a plugin are enabled by default and can be disabled or re-enabled in <code>/plugins</code>, then a new session must be started. See <a href="./plugins.html">Plugins</a> for details.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>stdio entries in a project-level <code>.kimi-code/mcp.json</code> execute local commands when a session starts. Only enable these in repositories you trust.</p></div><h2 id="tool-naming-and-permissions" tabindex="-1">Tool Naming and Permissions <a class="header-anchor" href="#tool-naming-and-permissions" aria-label="Permalink to &quot;Tool Naming and Permissions&quot;">​</a></h2><p>MCP tools are named in the format <code>mcp__&lt;server&gt;__&lt;tool&gt;</code>, for example <code>mcp__github__create_issue</code>. Permission rules support <code>*</code> and <code>**</code> wildcards, for example <code>mcp__github__*</code> matches all tools under that server. MCP tool parameters are not included in permission matching.</p><p>Calls that do not match any permission rule trigger an approval request. Selecting &quot;Approve for this session&quot; in the approval dialog automatically allows subsequent calls of the same kind within the current session.</p><p>You can also pre-configure permanent rules in <code>[[permission.rules]]</code> in <code>config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">decision = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp__github__*&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">decision = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deny&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp__filesystem__write_file&quot;</span></span></code></pre></div><p>For the full permission rule syntax, see <a href="./../configuration/config-files.html#permission">Configuration files</a>.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>When connecting to external MCP servers, be aware of:</p><ul><li>Only connect to servers from trusted sources</li><li>Verify that tool names and parameters look reasonable in approval requests</li><li>Keep manual approval for high-risk tools (file writes, command execution, etc.); avoid using <code>mcp__*</code> wildcards to allow all tools at once</li></ul><div class="warning custom-block"><p class="custom-block-title">Note</p><p>In YOLO mode, MCP tool calls are automatically approved. Only use this mode when you fully trust the MCP servers you have connected.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./plugins.html">Plugins</a> — Declare MCP servers in a plugin manifest to package and distribute them together</li><li><a href="./../configuration/config-files.html#permission">Configuration files</a> — Full field reference for permission rules</li></ul>`,32)])])}const k=s(a,[["render",n]]);export{u as __pageData,k as default};
